-- HAND-WRITTEN companion to schema.sql (not regenerated by dmtool). PermitRegistry 1.1.0.
-- CR-7 item 3: "expired" is a derived state, not a stored status (D-006).
-- Expired = status 'granted' and the validity end has passed. Validity end =
-- valid_until_date_time, else the end of the valid_until day in the authority's local time zone.
-- ASSUMPTION A-002: one local time zone for all authorities, set per database with
--   ALTER DATABASE ... SET permit_registry.local_time_zone = 'Europe/...';  (falls back to UTC)

CREATE OR REPLACE VIEW permit_registry.permit_with_expiry AS
SELECT p.*,
       coalesce(p.valid_until_date_time,
                ((p.valid_until + 1)::timestamp
                   AT TIME ZONE coalesce(nullif(current_setting('permit_registry.local_time_zone', true), ''), 'UTC'))
       ) AS effective_valid_until,
       (p.status = 'granted'
        AND coalesce(p.valid_until_date_time,
                     ((p.valid_until + 1)::timestamp
                        AT TIME ZONE coalesce(nullif(current_setting('permit_registry.local_time_zone', true), ''), 'UTC'))
            ) <= now()) AS expired,
       CASE WHEN p.status = 'granted'
             AND coalesce(p.valid_until_date_time,
                          ((p.valid_until + 1)::timestamp
                             AT TIME ZONE coalesce(nullif(current_setting('permit_registry.local_time_zone', true), ''), 'UTC'))
                 ) <= now()
            THEN 'expired' ELSE p.status::text END AS effective_status
FROM permit_registry.permit p
WHERE p.deleted_at IS NULL;

COMMENT ON VIEW permit_registry.permit_with_expiry IS 'Permits with derived expiry (CR-7 item 3, D-006). effective_status shows "expired" for granted permits whose validity end has passed.';
